#!/usr/bin/env python3
"""Materialize the original source closure and run the one native merchant worksheet workflow."""
import argparse,base64,hashlib,json,os,shutil,subprocess,sys,tempfile
from pathlib import Path

def decode(envelope):
    if envelope.get("schema")!="commons.source-packet/v1" or envelope.get("encoding")!="commons-lz77-v1+base64":
        raise ValueError("Use the original Commons source-packet format")
    expected=envelope.get("bytes")
    if not isinstance(expected,int) or not 0<expected<=64*1024*1024: raise ValueError("Invalid decoded byte bound")
    packed=base64.b64decode(envelope["data"],validate=True); plain=bytearray(); pos=0
    while pos<len(packed):
        flag=packed[pos];pos+=1
        if flag<128:
            count=flag+1
