            plain.extend(packed[pos:pos+count]);pos+=count
        else:
            count=flag-128+3
            if pos+2>len(packed): raise ValueError("Truncated source reference")
            distance=packed[pos]*256+packed[pos+1];pos+=2
            if not 1<=distance<=len(plain): raise ValueError("Invalid source reference")
            for _ in range(count):plain.append(plain[-distance])
        if len(plain)>expected: raise ValueError("Source exceeded its original byte bound")
    if len(plain)!=expected: raise ValueError("Source byte length changed")
    value=json.loads(plain.decode("utf-8"))
    if value.get("schema")!="stellar-forge.api-route-worksheet-native-source.v1":raise ValueError("Select the worksheet source packet")
    return value

def member(source,name):
    relative=Path(name)
    if relative.is_absolute() or ".." in relative.parts:raise ValueError("Invalid source member")
    target=source/relative
    if not target.parent.resolve().is_relative_to(source):raise ValueError("Source parent escapes its copy")
    return target

def main():
    parser=argparse.ArgumentParser()
    parser.add_argument("--packet",required=True)
    parser.add_argument("--donor",required=True)
    parser.add_argument("--parent",required=True)
    parser.add_argument("--node",default=os.environ.get("CODEX_PRIMARY_RUNTIME_NODE") or shutil.which("node"))
    args=parser.parse_args()
    packet=decode(json.loads(Path(args.packet).read_text()))
    donor=Path(args.donor).resolve(strict=True);parent=Path(args.parent).resolve(strict=True)
    if not donor.is_dir() or not parent.is_dir():raise ValueError("Select original installed source and existing private output parent")
    root=Path(tempfile.mkdtemp(prefix="d76c-route-worksheet-",dir=parent));root.chmod(0o700)
    source=root/"source";shutil.copytree(donor,source,symlinks=True)
    source_manifest=[]
    for name,content in packet.get("fallbackFiles",{}).items():
        target=member(source,name)
        if target.exists() or target.is_symlink():continue
        target.parent.mkdir(parents=True,exist_ok=True);target.write_text(content,encoding="utf-8")
    for name,value in packet["files"].items():
        data=value["content"].encode("utf-8") if "content" in value else base64.b64decode(value["base64"],validate=True)
        git_sha=hashlib.sha1(b"blob "+str(len(data)).encode()+b"\0"+data).hexdigest()
        if git_sha!=value["gitBlobSha"]:raise ValueError("Original Git source changed: "+name)
        target=member(source,name);target.parent.mkdir(parents=True,exist_ok=True)
        if target.is_symlink():target.unlink()
        target.write_bytes(data)
        if target.read_bytes()!=data:raise ValueError("Source readback changed: "+name)
        source_manifest.append({"path":name,"gitBlobSha":git_sha,"bytes":len(data)})
    inventory={"candidate":packet["candidate"],"donor":str(donor),"source":str(source),"files":source_manifest}
    (root/"source-selection.json").write_text(json.dumps(inventory,separators=(",",":")))
    argv=[args.node if item=="NODE" else str(root) if item=="ROOT" else str(source) if item=="SOURCE" else item for item in packet["argv"]]
    print(json.dumps({"state":"NATIVE_STARTING","root":str(root),"source":str(source),"candidate":packet["candidate"],"sourceFiles":len(source_manifest),"argv":argv}),flush=True)
    completed=subprocess.run(argv,cwd=source,env=os.environ.copy())
    print(json.dumps({"state":"NATIVE_EXITED","exitCode":completed.returncode,"root":str(root)}),flush=True)
    for result_file in sorted(root.glob("merchant-route-worksheet-*/result.json")):
        data=result_file.read_bytes()
        print(json.dumps({"state":"NATIVE_RESULT","path":str(result_file),"bytes":len(data),"sha256":hashlib.sha256(data).hexdigest(),"base64":base64.b64encode(data).decode()}),flush=True)
    return completed.returncode

if __name__=="__main__":sys.exit(main())

